theorem approxOn_trans {f g h : ℝ → ℝ} {X₁ X₂ ε₁ ε₂ : ℝ}
    (h1 : ApproxOn f g X₁ ε₁) (h2 : ApproxOn g h X₂ ε₂) :
    ApproxOn f h (min X₁ X₂) (ε₁ + ε₂)

theorem approxOn_trans_same {f g h : ℝ → ℝ} {X ε₁ ε₂ : ℝ}
    (h1 : ApproxOn f g X ε₁) (h2 : ApproxOn g h X ε₂) :
    ApproxOn f h X (ε₁ + ε₂)

theorem closure_fixpoint_subset_image {α : Type*} {T : Set α → Set α}
    (hT : IsClosureOperator T) {s t : Set α} (hfix : T s = s) (hsub : s ⊆ t) :
    s ⊆ T t

theorem piecewiseCompile_lipschitz_left (p : PiecewiseConstraint) {x y : ℝ}
    (hx : x ≤ p.c) (hy : y ≤ p.c) :
    |piecewiseCompile p x - piecewiseCompile p y| ≤ |p.fa| * |x - y|

theorem piecewiseCompile_lipschitz_right (p : PiecewiseConstraint) {x y : ℝ}
    (hx : p.c < x) (hy : p.c < y) :
    |piecewiseCompile p x - piecewiseCompile p y| ≤ |p.ga| * |x - y|
